/**
 * AI-IMAGE-OCR-SOURCE-01 — TEST ONLY images for tests.
 *
 * Nothing outside `tests/` imports this file. The text fixtures under
 * `tests/fixtures/image-ocr/` are synthetic rasters generated by
 * `generate-fixtures.ps1`; every one shows the TEST ONLY mark and has a file name
 * starting with TEST-ONLY. The images built here carry no text at all — a blank
 * page, or a header that declares enormous dimensions over almost no data — so
 * they need no mark in the picture; their callers name them TEST ONLY.
 */

import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { crc32, deflateSync } from 'node:zlib'

export const TEST_ONLY_MARK = 'TEST ONLY — NOT FOR PUBLICATION'

export type FixtureName =
  | 'TEST-ONLY-nameplate-en.png'
  | 'TEST-ONLY-nameplate-en.jpg'
  | 'TEST-ONLY-nameplate-en.webp'
  | 'TEST-ONLY-alpha.png'
  | 'TEST-ONLY-large-4200.png'
  | 'TEST-ONLY-orientation-6.jpg'
  | 'TEST-ONLY-chinese.png'
  | 'TEST-ONLY-multi-model.png'

export function fixture(name: FixtureName): Uint8Array {
  return new Uint8Array(readFileSync(resolve(process.cwd(), 'tests/fixtures/image-ocr', name)))
}

const PNG_SIGNATURE = Buffer.from([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A])

function chunk(type: string, data: Buffer): Buffer {
  const length = Buffer.alloc(4)
  length.writeUInt32BE(data.length)
  const body = Buffer.concat([Buffer.from(type, 'latin1'), data])
  const checksum = Buffer.alloc(4)
  checksum.writeUInt32BE(crc32(body) >>> 0)
  return Buffer.concat([length, body, checksum])
}

function header(width: number, height: number): Buffer {
  const data = Buffer.alloc(13)
  data.writeUInt32BE(width, 0)
  data.writeUInt32BE(height, 4)
  data[8] = 8 // bit depth
  data[9] = 2 // colour type: RGB
  return data
}

/** A valid PNG of one solid colour — white by default: a page with nothing on it. */
export function solidPng(width: number, height: number, rgb: [number, number, number] = [255, 255, 255]): Uint8Array {
  const row = Buffer.alloc(1 + width * 3)
  for (let x = 0; x < width; x += 1) row.set(rgb, 1 + x * 3)
  const raw = Buffer.concat(Array.from({ length: height }, () => row))
  return new Uint8Array(Buffer.concat([PNG_SIGNATURE, chunk('IHDR', header(width, height)), chunk('IDAT', deflateSync(raw)), chunk('IEND', Buffer.alloc(0))]))
}

/**
 * A PNG whose header declares `width` × `height` over one row of pixel data — a
 * few dozen bytes that would decode to an enormous bitmap. Its header reads; its
 * pixels do not.
 */
export function headerOnlyPng(width: number, height: number): Uint8Array {
  const oneRow = deflateSync(Buffer.alloc(1 + 3))
  return new Uint8Array(Buffer.concat([PNG_SIGNATURE, chunk('IHDR', header(width, height)), chunk('IDAT', oneRow), chunk('IEND', Buffer.alloc(0))]))
}

/** The first bytes of each format followed by noise: a signature that promises an image that is not there. */
export function brokenImage(type: 'jpeg' | 'png' | 'webp', size = 4096): Uint8Array {
  const bytes = new Uint8Array(size)
  for (let index = 0; index < size; index += 1) bytes[index] = (index * 2654435761) >>> 24
  if (type === 'jpeg') bytes.set([0xFF, 0xD8, 0xFF, 0xE0])
  if (type === 'png') bytes.set(PNG_SIGNATURE)
  if (type === 'webp') {
    bytes.set([0x52, 0x49, 0x46, 0x46])
    bytes.set([0x57, 0x45, 0x42, 0x50, 0x56, 0x50, 0x38, 0x20], 8)
  }
  return bytes
}

/** Tesseract TSV output for the given lines of `[word, confidence]`, as the sidecar receives it. */
export function tesseractTsv(lines: Array<Array<[string, number]>>): string {
  const rows = ['level\tpage_num\tblock_num\tpar_num\tline_num\tword_num\tleft\ttop\twidth\theight\tconf\ttext', '1\t1\t0\t0\t0\t0\t0\t0\t1400\t520\t-1\t']
  lines.forEach((words, lineIndex) => {
    rows.push(`4\t1\t1\t1\t${lineIndex + 1}\t0\t0\t0\t100\t20\t-1\t`)
    words.forEach(([text, confidence], wordIndex) => {
      rows.push(`5\t1\t1\t1\t${lineIndex + 1}\t${wordIndex + 1}\t0\t0\t10\t10\t${confidence}\t${text}`)
    })
  })
  return `${rows.join('\n')}\n`
}
